SELECT u2.ID, u2.FILE_NAME,u1.LE as LEVEL,u2.PARENT_ID,u2.CREATE_TIME,u2.FILE_PATH
FROM(
        SELECT
            @ids AS p_ids,
            (SELECT @ids := GROUP_CONCAT(ID) FROM PAN_USER_FILE

                            DELETE_FLAG = 'NOT_DELETE' AND IS_DIR = 1

                                AND FOLD_TYPE IN

                                    #{foldType}



                                AND USER_ID  = #{userId}


                                AND ORG_ID IN

                                    #{orgId}



                    AND  FIND_IN_SET(PARENT_ID, @ids)) AS c_ids,
    @l := @l+1 AS LE
FROM PAN_USER_FILE, (SELECT @ids := ${id}, @l := 0 ) b
    WHERE @ids IS NOT NULL
    ) u1
    JOIN PAN_USER_FILE u2
ON FIND_IN_SET(u2.ID, u1.p_ids)

